import java.io.Serializable;

public class JobEvent implements Serializable {

    public static final int SUBMIT = 0;
    public static final int SCHEDULE = 1;
    public static final int FAIL = 3;
    public static final int FINISH = 4;
    public static final int KILL = 5;
    public static final int LOST = 6;

    public long timestampMicros;
    public long jobId;
    public int eventType;

    public JobEvent() {
    }

    public JobEvent(long timestampMicros, long jobId, int eventType) {
        this.timestampMicros = timestampMicros;
        this.jobId = jobId;
        this.eventType = eventType;
    }

    public long getTimestampMicros() {
        return timestampMicros;
    }

    public long getJobId() {
        return jobId;
    }

    public int getEventType() {
        return eventType;
    }

    public boolean isTerminal() {
        return eventType == FAIL || eventType == FINISH || eventType == KILL || eventType == LOST;
    }

    public static JobEvent fromCsv(String line) {
        // job_events schema (v2.1) begins with:
        // timestamp, missing_info, job_id, event_type, ...
        String[] p = line.split(",", -1);
        long ts = parseLong(p, 0);
        long jobId = parseLong(p, 2);
        int eventType = (int) parseLong(p, 3);
        return new JobEvent(ts, jobId, eventType);
    }

    private static long parseLong(String[] p, int idx) {
        if (p.length <= idx) {
            return -1L;
        }
        String s = p[idx];
        if (s == null || s.isEmpty()) {
            return -1L;
        }
        return Long.parseLong(s);
    }
}
"}

