import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.RuntimeExecutionMode;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.common.typeinfo.Types;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.core.fs.FileSystem;
import org.apache.flink.streaming.api.datastream.ConnectedStreams;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.co.KeyedCoProcessFunction;
import org.apache.flink.streaming.api.functions.sink.SinkFunction;
import org.apache.flink.util.Collector;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);

        final int sesssizeSeconds = params.getInt("sesssize", 600);
        final long gapMs = sesssizeSeconds * 1_000L;

        // set up execution environment
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setRuntimeMode(RuntimeExecutionMode.BATCH);
        env.setParallelism(1);

        DataStream<TaskEvent> taskStream;
        if (AppBase.taskEvents != null) {
            taskStream = env.addSource(AppBase.taskEvents).name("taskEvents-test");
        } else {
            taskStream = env.readTextFile(taskInput)
                    .name("taskEvents-file")
                    .map(TaskEvent::fromCsv)
                    .returns(TaskEvent.class);
        }

        DataStream<JobEvent> jobStream;
        if (AppBase.jobEvents != null) {
            jobStream = env.addSource(AppBase.jobEvents).name("jobEvents-test");
        } else {
            jobStream = env.readTextFile(jobInput)
                    .name("jobEvents-file")
                    .map(JobEvent::fromCsv)
                    .returns(JobEvent.class);
        }

        WatermarkStrategy<TaskEvent> taskWm = WatermarkStrategy
                .<TaskEvent>forMonotonousTimestamps()
                .withTimestampAssigner((e, ts) -> e.timestampMicros / 1_000L);

        WatermarkStrategy<JobEvent> jobWm = WatermarkStrategy
                .<JobEvent>forMonotonousTimestamps()
                .withTimestampAssigner((e, ts) -> e.timestampMicros / 1_000L);

        DataStream<TaskEvent> submitTasks = taskStream
                .filter(e -> e != null && e.eventType == TaskEvent.SUBMIT)
                .assignTimestampsAndWatermarks(taskWm);

        DataStream<JobEvent> terminalJobs = jobStream
                .filter(e -> e != null && e.isTerminal())
                .assignTimestampsAndWatermarks(jobWm);

        ConnectedStreams<TaskEvent, JobEvent> connected = submitTasks
                .keyBy(TaskEvent::getJobId)
                .connect(terminalJobs.keyBy(JobEvent::getJobId));

        DataStream<Tuple2<Long, Integer>> longestStagePerFinishedJob = connected
                .process(new LongestStageUntilFinished(gapMs))
                .name("longest-stage-per-job")
                .returns(Types.TUPLE(Types.LONG, Types.INT));

        DataStream<String> formatted = longestStagePerFinishedJob
                .map(t -> "(" + t.f0 + "," + t.f1 + ")")
                .returns(Types.STRING);

        if (AppBase.out != null) {
            formatted.addSink((SinkFunction<String>) AppBase.out).name("out-test");
        } else {
            formatted.writeAsText(outputPath, FileSystem.WriteMode.OVERWRITE)
                    .name("out-file")
                    .setParallelism(1);
        }

        env.execute("LongestSessionPerJob");
    }

    /**
     * Builds inactivity-gap "stages" from SUBMIT task events and emits the longest stage
     * size once a terminal job event is observed.
     */
    public static class LongestStageUntilFinished extends KeyedCoProcessFunction<Long, TaskEvent, JobEvent, Tuple2<Long, Integer>> {

        private final long gapMs;

        private transient ValueState<Long> lastSubmitTsMs;
        private transient ValueState<Integer> currentStageCount;
        private transient ValueState<Integer> maxStageCount;

        private transient ValueState<Long> stageCloseTimerTsMs;

        private transient ValueState<Long> terminalJobTsMs;
        private transient ValueState<Long> terminalTimerTsMs;

        private transient ValueState<Boolean> emitted;

        public LongestStageUntilFinished(long gapMs) {
            this.gapMs = gapMs;
        }

        @Override
        public void open(org.apache.flink.configuration.Configuration parameters) {
            lastSubmitTsMs = getRuntimeContext().getState(new ValueStateDescriptor<>("lastSubmitTsMs", Long.class));
            currentStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("currentStageCount", Integer.class));
            maxStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("maxStageCount", Integer.class));
            stageCloseTimerTsMs = getRuntimeContext().getState(new ValueStateDescriptor<>("stageCloseTimerTsMs", Long.class));
            terminalJobTsMs = getRuntimeContext().getState(new ValueStateDescriptor<>("terminalJobTsMs", Long.class));
            terminalTimerTsMs = getRuntimeContext().getState(new ValueStateDescriptor<>("terminalTimerTsMs", Long.class));
            emitted = getRuntimeContext().getState(new ValueStateDescriptor<>("emitted", Boolean.class));
        }

        @Override
        public void processElement1(TaskEvent e, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            if (Boolean.TRUE.equals(emitted.value())) {
                return;
            }

            long tsMs = e.timestampMicros / 1_000L;

            Integer cur = currentStageCount.value();
            if (cur == null) {
                cur = 0;
            }
            Integer max = maxStageCount.value();
            if (max == null) {
                max = 0;
            }

            Long lastTs = lastSubmitTsMs.value();
            if (cur == 0) {
                cur = 1;
            } else if (lastTs != null && tsMs - lastTs > gapMs) {
                max = Math.max(max, cur);
                cur = 1;
            } else {
                cur = cur + 1;
            }

            currentStageCount.update(cur);
            maxStageCount.update(max);
            lastSubmitTsMs.update(tsMs);

            Long oldStageTimer = stageCloseTimerTsMs.value();
            if (oldStageTimer != null) {
                ctx.timerService().deleteEventTimeTimer(oldStageTimer);
            }
            long newStageTimer = tsMs + gapMs;
            ctx.timerService().registerEventTimeTimer(newStageTimer);
            stageCloseTimerTsMs.update(newStageTimer);
        }

        @Override
        public void processElement2(JobEvent e, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            if (Boolean.TRUE.equals(emitted.value())) {
                return;
            }

            long tsMs = e.timestampMicros / 1_000L;
            Long prev = terminalJobTsMs.value();
            if (prev == null || tsMs > prev) {
                terminalJobTsMs.update(tsMs);

                Long old = terminalTimerTsMs.value();
                if (old != null) {
                    ctx.timerService().deleteEventTimeTimer(old);
                }
                ctx.timerService().registerEventTimeTimer(tsMs);
                terminalTimerTsMs.update(tsMs);
            }
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            if (Boolean.TRUE.equals(emitted.value())) {
                return;
            }

            Integer max = maxStageCount.value();
            if (max == null) {
                max = 0;
            }

            Long stageTimer = stageCloseTimerTsMs.value();
            if (stageTimer != null && timestamp == stageTimer) {
                Integer cur = currentStageCount.value();
                if (cur != null && cur > 0) {
                    max = Math.max(max, cur);
                    maxStageCount.update(max);
                }
                currentStageCount.update(0);
                stageCloseTimerTsMs.clear();
            }

            Long terminalTs = terminalJobTsMs.value();
            if (terminalTs == null) {
                return;
            }

            Integer cur = currentStageCount.value();
            if (cur == null) {
                cur = 0;
            }

            boolean stageClosed = cur == 0;
            boolean afterTerminal = timestamp >= terminalTs;

            if (stageClosed && afterTerminal) {
                out.collect(Tuple2.of(ctx.getCurrentKey(), max));
                emitted.update(true);

                lastSubmitTsMs.clear();
                currentStageCount.clear();
                maxStageCount.clear();
                stageCloseTimerTsMs.clear();
                terminalJobTsMs.clear();
                terminalTimerTsMs.clear();
            }
        }
    }
}
"}

