     * size once a terminal job event is observed.
     */
    public static class LongestStageUntilFinished extends KeyedCoProcessFunction<Long, TaskEvent, JobEvent, Tuple2<Long, Integer>> {

        private final long gapMs;

        private transient ValueState<Long> lastSubmitTsMs;
        private transient ValueState<Integer> currentStageCount;
        private transient ValueState<Integer> maxStageCount;

        private transient ValueState<Long> stageCloseTimerTsMs;

        private transient ValueState<Long> terminalJobTsMs;
        private transient ValueState<Long> terminalTimerTsMs;

        private transient ValueState<Boolean> emitted;

        public LongestStageUntilFinished(long gapMs) {
            this.gapMs = gapMs;
        }

        @Override
        public void open(org.apache.flink.configuration.Configuration parameters) {
            lastSubmitTsMs = getRuntimeContext().getState(new ValueStateDescriptor<>("lastSubmitTsMs", Long.class));
            currentStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("currentStageCount", Integer.class));
            maxStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("maxStageCount", Integer.class));
            stageCloseTimerTsMs = getRuntimeContext().getState(new ValueStateDescriptor<>("stageCloseTimerTsMs", Long.class));
            terminalJobTsMs = getRuntimeContext().getState(new ValueStateDescriptor<>("terminalJobTsMs", Long.class));
            terminalTimerTsMs = getRuntimeContext().getState(new ValueStateDescriptor<>("terminalTimerTsMs", Long.class));
            emitted = getRuntimeContext().getState(new ValueStateDescriptor<>("emitted", Boolean.class));
        }

        @Override
        public void processElement1(TaskEvent e, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            if (Boolean.TRUE.equals(emitted.value())) {
                return;
            }

            long tsMs = e.timestampMicros / 1_000L;

            Integer cur = currentStageCount.value();
            if (cur == null) {
                cur = 0;
            }
            Integer max = maxStageCount.value();
            if (max == null) {
                max = 0;
            }

            Long lastTs = lastSubmitTsMs.value();
            if (cur == 0) {
                cur = 1;
            } else if (lastTs != null && tsMs - lastTs > gapMs) {
                max = Math.max(max, cur);
                cur = 1;
            } else {
                cur = cur + 1;
            }

            currentStageCount.update(cur);
            maxStageCount.update(max);
            lastSubmitTsMs.update(tsMs);

            Long oldStageTimer = stageCloseTimerTsMs.value();
            if (oldStageTimer != null) {
                ctx.timerService().deleteEventTimeTimer(oldStageTimer);
            }
            long newStageTimer = tsMs + gapMs;
            ctx.timerService().registerEventTimeTimer(newStageTimer);
            stageCloseTimerTsMs.update(newStageTimer);
        }

        @Override
        public void processElement2(JobEvent e, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            if (Boolean.TRUE.equals(emitted.value())) {
                return;
            }

            long tsMs = e.timestampMicros / 1_000L;
            Long prev = terminalJobTsMs.value();
            if (prev == null || tsMs > prev) {
                terminalJobTsMs.update(tsMs);

                Long old = terminalTimerTsMs.value();
                if (old != null) {
                    ctx.timerService().deleteEventTimeTimer(old);
                }
                ctx.timerService().registerEventTimeTimer(tsMs);
                terminalTimerTsMs.update(tsMs);
            }
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            if (Boolean.TRUE.equals(emitted.value())) {
                return;
            }

            Integer max = maxStageCount.value();
            if (max == null) {
                max = 0;
            }

            Long stageTimer = stageCloseTimerTsMs.value();
            if (stageTimer != null && timestamp == stageTimer) {
                Integer cur = currentStageCount.value();
                if (cur != null && cur > 0) {
                    max = Math.max(max, cur);
                    maxStageCount.update(max);
                }
                currentStageCount.update(0);
                stageCloseTimerTsMs.clear();
            }

            Long terminalTs = terminalJobTsMs.value();
            if (terminalTs == null) {
                return;
            }

            Integer cur = currentStageCount.value();
            if (cur == null) {
                cur = 0;
            }

            boolean stageClosed = cur == 0;
            boolean afterTerminal = timestamp >= terminalTs;

            if (stageClosed && afterTerminal) {
                out.collect(Tuple2.of(ctx.getCurrentKey(), max));
                emitted.update(true);

                lastSubmitTsMs.clear();
                currentStageCount.clear();
                maxStageCount.clear();
                stageCloseTimerTsMs.clear();
                terminalJobTsMs.clear();
                terminalTimerTsMs.clear();
            }
        }
    }
}
